 'installed_contract_exact',i='{"guards":[["advisory_advice_records","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_advice_records FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_deliverables","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_deliverables FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_issue_tasks","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issue_tasks FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_issues","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issues FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_journey_snapshots","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_journey_snapshots FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_activities","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_activities FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_control","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_control FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_stages","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_stages FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_team","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_team FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matters","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matters FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''id'')"],["advisory_stage_visits","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_stage_visits FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_time_logs","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_time_logs FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_work_state_events","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_work_state_events FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"]],"functions":{"advisory095_capture()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_capture()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$ WITH targets(id,matter_no) AS (VALUES (''8f375864-0fb3-4d17-9e07-d4f6d76cf4fe''::uuid,''ADV-2026-013''),(''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid,''ADV-2026-014''),(''02e5ba61-af9b-4dc0-8729-9e334639b652''::uuid,''ADV-2026-015''),(''c9aa7141-ed6a-4cdd-926a-ad261fb93dd6''::uuid,''ADV-2026-016''),(''47bfb55e-3ac5-445c-b335-5d48417f793e''::uuid,''ADV-2026-017''),(''7442060f-5a6b-4235-a826-597a6a53bb37''::uuid,''ADV-2026-018''),(''b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0''::uuid,''ADV-2026-019''),(''6c717f2e-aff6-44af-9774-e910d7a61047''::uuid,''ADV-2026-020''),(''35583652-f594-4d7b-8f6a-24991df14dad''::uuid,''ADV-2026-021''),(''50221a99-f188-4f18-9017-b6f3302a5c2f''::uuid,''ADV-2026-022''),(''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid,''ADV-2026-023'')),\n rels AS MATERIALIZED (SELECT c.oid,n.nspname,c.relname,c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN (''r'',''p'') AND NOT c.relispartition\n AND (n.nspname=''public'' AND c.relname<>''advisory_matter_archives'' OR n.nspname=''auth'' AND c.relname=''users'' OR n.nspname=''storage'' AND c.relname IN (''buckets'',''objects''))),\n rows AS MATERIALIZED (SELECT r.nspname||''.''||r.relname name,x.evidence::jsonb evidence FROM rels r CROSS JOIN LATERAL XMLTABLE(''/table/row'' PASSING query_to_xml(format(\n ''SELECT jsonb_build_object(''''count'''',count(*),''''sha256'''',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE \"C\"),''''[]''''::jsonb)::text,''''UTF8'''')),''''hex''''))::text evidence FROM %I.%I t'',r.nspname,r.relname),false,false,'''') COLUMNS evidence text PATH ''evidence'') x),\n catalog AS MATERIALIZED (SELECT n.nspname||''.''||c.relname name,jsonb_build_object(''kind'',c.relkind,''owner'',pg_get_userbyid(c.relowner),''acl'',c.relacl::text,''rls'',c.relrowsecurity,''force_rls'',c.relforcerowsecurity,''options'',c.reloptions,\n ''view'',CASE WHEN c.relkind=''v'' THEN pg_get_viewdef(c.oid,true) END,\n ''columns'',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),\n ''constraints'',(SELECT coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid,true),k.convalidated) ORDER BY k.conname COLLATE \"C\"),''[]'') FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>''n''),\n ''indexes'',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY ic.relname COLLATE \"C\"),''[]'') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),\n ''policies'',(SELECT coalesce(jsonb_agg(to_jsonb(p)-''schemaname''-''tablename'' ORDER BY p.policyname COLLATE \"C\"),''[]'') FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),\n ''triggers'',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname COLLATE \"C\"),''[]'') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname NOT LIKE ''advisory095_%'')) evidence FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n WHERE c.relkind IN (''r'',''p'',''v'',''m'',''S'') AND NOT c.relispartition AND (n.nspname=''public'' AND NOT (c.relname=''advisory_matter_archives'' OR c.relname IN (''advisory_operational_matters'',''advisory_operational_issues'',''advisory_operational_tasks'',''advisory_operational_time'',''advisory_operational_advice'')) OR n.nspname=''auth'' AND c.relname=''users'' OR n.nspname=''storage'' AND c.relname IN (''objects'',''buckets''))),\n funcs AS MATERIALIZED (SELECT p.oid::regprocedure::text name,jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) evidence FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND p.prokind IN (''f'',''p'') AND p.proname NOT LIKE ''advisory095_%'' AND p.oid::regprocedure::text NOT IN (''advisory_control_read(uuid,jsonb)'',''advisory_control_section(uuid,text,integer,uuid)'',''advisory_overdue_work(uuid)'',''advisory_workflow_checks(uuid)'')),\n target_rows AS MATERIALIZED (SELECT t.*,to_jsonb(m) facts FROM targets t LEFT JOIN public.advisory_matters m ON m.id=t.id AND m.matter_no=t.matter_no),\n tokens AS MATERIALIZED (SELECT array_agg(DISTINCT token) ids FROM (\n SELECT id::text token FROM targets UNION SELECT matter_no FROM targets\n UNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issues x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issue_tasks x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_time_logs x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_advice_records x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_control x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_team x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_stages x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_stage_visits x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_journey_snapshots x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_activities x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_work_state_events x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_deliverables x JOIN targets t ON t.id=x.matter_id\n ) x WHERE token IS NOT NULL),\n ref_columns AS (SELECT n.nspname,c.relname,a.attname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped\n WHERE n.nspname=''public'' AND c.relkind IN (''r'',''p'') AND NOT c.relispartition AND (c.relname LIKE ''finance_%'' OR c.relname=''cases'' OR c.relname LIKE ''case_%'') AND c.relname<>''case_audit_logs''\n AND (a.atttypid IN (''json''::regtype,''jsonb''::regtype) OR a.attname ~ ''(advisory|matter|issue|task|source|origin|record|entity|object|target).*(id|ids|no|reference)$''\n OR EXISTS(SELECT 1 FROM pg_constraint k WHERE k.contype=''f'' AND k.conrelid=c.oid AND a.attnum=ANY(k.conkey) AND k.confrelid IN(SELECT to_regclass(''public.''||x) FROM unnest(ARRAY[''advisory_matters'',''advisory_issues'',''advisory_issue_tasks'',''advisory_time_logs'',''advisory_advice_records'',''advisory_matter_control'',''advisory_matter_team'',''advisory_matter_stages'',''advisory_stage_visits'',''advisory_journey_snapshots'',''advisory_matter_activities'',''advisory_work_state_events'',''advisory_deliverables'']) x)))),\n refs AS MATERIALIZED (SELECT r.relname table_name,x.n FROM (SELECT nspname,relname,string_agg(format(''EXISTS(SELECT 1 FROM unnest(%L::text[]) tok WHERE strpos(coalesce(r.%I::text,''''''''),tok)>0)'',tokens.ids::text,attname),'' OR '' ORDER BY attname) predicate FROM ref_columns CROSS JOIN tokens GROUP BY nspname,relname) r\n CROSS JOIN LATERAL XMLTABLE(''/table/row'' PASSING query_to_xml(format(''SELECT count(*)::bigint n FROM %I.%I r WHERE %s'',r.nspname,r.relname,r.predicate),false,false,'''') COLUMNS n bigint PATH ''n'') x WHERE x.n>0),\n raw AS (SELECT (SELECT jsonb_object_agg(name,evidence) FROM rows) rows,\n jsonb_build_object(''relations'',(SELECT jsonb_object_agg(name,evidence) FROM catalog),''functions'',(SELECT jsonb_object_agg(name,evidence) FROM funcs),\n ''roles'',(SELECT jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolbypassrls) ORDER BY rolname COLLATE \"C\") FROM pg_roles),\n ''members'',(SELECT jsonb_agg(jsonb_build_array(roleid::regrole::text,member::regrole::text,admin_option) ORDER BY roleid::regrole::text COLLATE \"C\",member::regrole::text COLLATE \"C\") FROM pg_auth_members)) preserved,\n (SELECT jsonb_agg(jsonb_build_object(''id'',id,''matter_no'',matter_no,''sha256'',encode(sha256(convert_to((facts)::text,''UTF8'')),''hex'')) ORDER BY matter_no COLLATE \"C\") FROM target_rows) targets,\n (SELECT count(*)=11 AND bool_and(facts IS NOT NULL) FROM target_rows) AND (SELECT count(*)=11 FROM public.advisory_matters WHERE matter_no IN(SELECT matter_no FROM targets)) targets_exact)\n SELECT jsonb_build_object(''rows_sha256'',encode(sha256(convert_to((rows)::text,''UTF8'')),''hex''),''preserved_sha256'',encode(sha256(convert_to((preserved)::text,''UTF8'')),''hex''),''targets_sha256'',encode(sha256(convert_to((targets)::text,''UTF8'')),''hex''),\n ''row_fingerprints'',rows,''targets'',targets,''targets_exact'',targets_exact,\n ''protected_count'',(SELECT count(*) FROM public.advisory_matters WHERE matter_no=ANY(ARRAY[''ADV-2026-004'',''ADV-2026-005'',''ADV-2026-006'',''ADV-2026-007'',''ADV-2026-008'',''ADV-2026-009'',''ADV-2026-010'',''ADV-2026-011'',''ADV-2026-012''])),\n ''external_references'',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY table_name COLLATE \"C\"),''[]'') FROM refs r),\n ''reviewed_special_evidence'',jsonb_build_object(''time_023_minutes'',(SELECT coalesce(sum(minutes),0) FROM public.advisory_time_logs WHERE advisory_matter_id=''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid),\n ''snapshot_matters'',(SELECT coalesce(jsonb_agg(m.matter_no ORDER BY m.matter_no COLLATE \"C\"),''[]'') FROM public.advisory_journey_snapshots s JOIN public.advisory_matters m ON m.id=s.matter_id WHERE m.matter_no=ANY(ARRAY[''ADV-2026-019'',''ADV-2026-020'',''ADV-2026-021'',''ADV-2026-022'',''ADV-2026-023''])),\n ''audit_014_count'',(SELECT count(*) FROM public.case_audit_logs a WHERE a.table_name LIKE ''advisory_%'' AND a.record_id IN(\n SELECT ''7583d780-9e98-4852-bf5a-98c40fbf8072'' UNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issues x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issue_tasks x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_time_logs x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_advice_records x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_control x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_team x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_stages x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_stage_visits x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_journey_snapshots x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_activities x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_work_state_events x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_deliverables x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid)))) FROM raw; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory095_targets()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_targets()\n RETURNS TABLE(id uuid, matter_no text)\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$ VALUES (''8f375864-0fb3-4d17-9e07-d4f6d76cf4fe''::uuid,''ADV-2026-013''),(''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid,''ADV-2026-014''),(''02e5ba61-af9b-4dc0-8729-9e334639b652''::uuid,''ADV-2026-015''),(''c9aa7141-ed6a-4cdd-926a-ad261fb93dd6''::uuid,''ADV-2026-016''),(''47bfb55e-3ac5-445c-b335-5d48417f793e''::uuid,''ADV-2026-017''),(''7442060f-5a6b-4235-a826-597a6a53bb37''::uuid,''ADV-2026-018''),(''b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0''::uuid,''ADV-2026-019''),(''6c717f2e-aff6-44af-9774-e910d7a61047''::uuid,''ADV-2026-020''),(''35583652-f594-4d7b-8f6a-24991df14dad''::uuid,''ADV-2026-021''),(''50221a99-f188-4f18-9017-b6f3302a5c2f''::uuid,''ADV-2026-022''),(''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid,''ADV-2026-023''); $function$\n","volatility":"i","service_role":false,"authenticated":false},"advisory095_write_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE ids uuid[]; k uuid;\nBEGIN\n ids:=ARRAY[CASE WHEN TG_OP<>''DELETE'' THEN (to_jsonb(NEW)->>TG_ARGV[0])::uuid END,\n            CASE WHEN TG_OP<>''INSERT'' THEN (to_jsonb(OLD)->>TG_ARGV[0])::uuid END];\n FOR k IN SELECT DISTINCT x FROM unnest(ids) x WHERE x IS NOT NULL ORDER BY x LOOP\n  PERFORM 1 FROM public.advisory_matters WHERE id=k FOR UPDATE;\n  IF EXISTS(SELECT 1 FROM public.advisory_matter_archives WHERE matter_id=k) THEN\n   RAISE EXCEPTION ''ADVISORY_ARCHIVED'' USING ERRCODE=''55000'';\n  END IF;\n END LOOP;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_overdue_work(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_overdue_work(p_matter_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(matter_id uuid, source text, source_id uuid, title text, assignee_user_id uuid, assignee_name text, due_date date, overdue_days integer, is_next_action boolean)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n -- Invoker/RLS remains authoritative. Identity is (source, source_id), never title.\n return query\n with open_matters as materialized (\n  select m.id,c.next_task_id,c.next_action,c.next_owner_id,c.next_due\n  from public.advisory_operational_matters m left join public.advisory_matter_control c on c.matter_id=m.id\n  where (p_matter_id is null or m.id=p_matter_id)\n   and m.status not in (''completed'',''cancelled'') and c.closed_at is null\n )\n select m.id,''task''::text,t.id,t.title,t.assignee_user_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name,t.assignee_name),t.due_date,today-t.due_date,\n  coalesce(m.next_task_id=t.id,false)\n from open_matters m join public.advisory_issue_tasks t on t.advisory_matter_id=m.id\n left join public.user_profiles p on p.id=t.assignee_user_id\n where t.deleted_at is null and t.completed_at is null\n  and t.status in (''pending'',''in_progress'',''waiting'') and t.due_date<today\n union all\n select m.id,''next_action''::text,m.id,m.next_action,m.next_owner_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name),m.next_due,today-m.next_due,true\n from open_matters m left join public.user_profiles p on p.id=m.next_owner_id\n where m.next_task_id is null and nullif(btrim(m.next_action),'''') is not null and m.next_due<today;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_operational(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_operational(p_matter_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT public.advisory076_allowed(''read'') AND NOT EXISTS(\n  SELECT 1 FROM public.advisory_matter_archives a WHERE a.matter_id=p_matter_id);\n$function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_workflow_checks(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_workflow_checks(p_matter_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare m public.advisory_matters%rowtype; c public.advisory_matter_control%rowtype;\n visit public.advisory_stage_visits%rowtype; stage public.advisory_matter_stages%rowtype;\n open_tasks bigint; pending_deliverables bigint; uncompleted_stages bigint; stage_open_tasks bigint;\n has_next boolean; result jsonb; fj jsonb; options jsonb;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n select * into m from public.advisory_operational_matters where id=p_matter_id;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n select * into c from public.advisory_matter_control where matter_id=m.id;\n select * into visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n select * into stage from public.advisory_matter_stages where id=visit.stage_id;\n select count(*) into open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into stage_open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=stage.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into pending_deliverables from public.advisory_deliverables where matter_id=m.id and status not in (''delivered'',''cancelled'');\n select count(*) into uncompleted_stages from public.advisory_matter_stages s where s.matter_id=m.id and s.stage_key<>''close''\n and not exists(select 1 from public.advisory_stage_visits v where v.stage_id=s.id and\n  (v.kind=''skip'' or (v.kind=''visit'' and v.exited_at is not null)));\n select definition into fj from public.advisory_journey_snapshots where matter_id=m.id;\n if fj->''format''=''2''::jsonb then\n  select s->''outcomes'' into options from jsonb_array_elements(fj->''stages'') s where s->>''key''=stage.stage_key;\n  -- Only the actual chosen route affects closing; unchosen branches are not\n  -- incomplete work, and no skip/history is fabricated for them.\n  uncompleted_stages:=case when visit.id is null and exists(\n   select 1 from public.advisory_matter_activities a where a.matter_id=m.id and a.kind in (''stage_complete'',''stage_skip'')\n    and a.detail->>''journey_format''=''2'' and a.detail->>''next_stage_key''=''close''\n    and a.detail->>''from_visit_id''=(select v.id::text from public.advisory_stage_visits v where v.matter_id=m.id and v.kind=''visit'' order by v.entered_at desc,v.recorded_at desc,v.id desc limit 1)\n  ) then 0 else 1 end;\n end if;\n has_next:=c.next_task_id is not null or c.next_action is not null;\n result:=jsonb_build_object(''matter_id'',m.id,''version'',coalesce(c.version,0),''lifecycle'',m.status,\n  ''closed'',c.closed_at is not null or m.status in (''completed'',''cancelled''),\n  ''current_visit_id'',visit.id,''current_stage_id'',stage.id,''current_stage_key'',stage.stage_key,\n  ''current_stage_open_tasks'',stage_open_tasks,''open_tasks'',open_tasks,''has_next_action'',has_next,\n  ''pending_deliverables'',pending_deliverables,''uncompleted_stages'',uncompleted_stages,\n  ''stage_ready'',visit.id is null and uncompleted_stages=0,\n  ''legacy_without_plan'',not exists(select 1 from public.advisory_matter_stages where matter_id=m.id),\n  ''ready_to_close'',open_tasks=0 and not has_next and pending_deliverables=0 and visit.id is null and uncompleted_stages=0);\n if fj->''format''=''2''::jsonb then result:=result||jsonb_build_object(''journey_format'',2,''outcomes'',coalesce(options,''[]''::jsonb),\n  ''route_stages'',(select jsonb_agg(s-''outcomes'' order by n) from jsonb_array_elements(fj->''stages'') with ordinality x(s,n))); end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_archive_immutable()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_archive_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nBEGIN RAISE EXCEPTION ''ADVISORY_ARCHIVE_IMMUTABLE''; END $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_control_read(uuid,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_read(p_matter_id uuid DEFAULT NULL::uuid, p_query jsonb DEFAULT ''{}''::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare result jsonb; today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n with overdue_items as materialized (select * from public.advisory_overdue_work()),\n ranked_overdue as (\n  select o.*,row_number() over(partition by matter_id order by due_date,source COLLATE \"C\",source_id) position from overdue_items o\n ), overdue as (\n  select matter_id,count(*) overdue_item_count,min(due_date) oldest_overdue_due,max(overdue_days) oldest_overdue_days,\n   coalesce(max(overdue_days) filter(where is_next_action),0) next_action_overdue_days,\n   jsonb_agg(to_jsonb(o)-''matter_id''-''position'' order by due_date,source COLLATE \"C\",source_id) filter(where position<=3) overdue_preview\n  from ranked_overdue o group by matter_id\n ), items as (\n select m.*,coalesce(o.overdue_item_count,0)>0 has_overdue_work,\n coalesce(o.overdue_item_count,0) overdue_item_count,o.oldest_overdue_due,coalesce(o.oldest_overdue_days,0) oldest_overdue_days,\n coalesce(o.next_action_overdue_days,0) next_action_overdue_days,coalesce(o.overdue_preview,''[]''::jsonb) overdue_preview,\n cl.name client_name,coalesce(c.version,0) version,c.work_state,c.closed_at,c.outcome,c.outcome_summary,c.follow_up,c.case_reference,\n c.next_task_id,coalesce(t.title,c.next_action) next_action,coalesce(t.assignee_user_id,c.next_owner_id) next_owner_id,\n coalesce(nullif(np.staff_name,''''),np.full_name,t.assignee_name) next_owner_name,coalesce(t.due_date,c.next_due) next_due,\n lead.user_id lead_id,coalesce(nullif(lp.staff_name,''''),lp.full_name,m.responsible_lawyer) lead_name,\n st.stage_key,st.template_key,v.entered_at,\n (select s->>''name_th'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_th,\n (select s->>''name_en'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_en,\n case when v.entered_at is not null then greatest(0,today-(v.entered_at at time zone ''Asia/Bangkok'')::date) end stage_days,\n greatest(0,coalesce((c.closed_at at time zone ''Asia/Bangkok'')::date,today)-coalesce(m.start_date,(m.created_at at time zone ''Asia/Bangkok'')::date)) age_days\n from public.advisory_operational_matters m join public.clients cl on cl.id=m.client_id\n left join overdue o on o.matter_id=m.id\n left join public.advisory_matter_control c on c.matter_id=m.id\n left join public.advisory_issue_tasks t on t.id=c.next_task_id and t.deleted_at is null and t.status in (''pending'',''in_progress'',''waiting'') and t.completed_at is null\n left join public.user_profiles np on np.id=coalesce(t.assignee_user_id,c.next_owner_id)\n left join public.advisory_matter_team lead on lead.matter_id=m.id and lead.team_role=''lead''\n left join public.user_profiles lp on lp.id=lead.user_id\n left join public.advisory_stage_visits v on v.matter_id=m.id and v.kind=''visit'' and v.exited_at is null\n left join public.advisory_matter_stages st on st.id=v.stage_id\n ), filtered as (\n select * from items i where (p_matter_id is null or i.id=p_matter_id)\n and (coalesce(p_query->>''search'','''')='''' or concat_ws('' '',i.matter_no,i.title,i.client_name,i.lead_name) ilike ''%''||(p_query->>''search'')||''%'')\n and (coalesce(p_query->>''client_id'','''')='''' or i.client_id::text=p_query->>''client_id'')\n and (coalesce(p_query->>''type'','''')='''' or i.matter_type=p_query->>''type'')\n and (coalesce(p_query->>''lead'','''')='''' or i.lead_id::text=p_query->>''lead'')\n and (coalesce(p_query->>''state'','''')='''' or i.work_state=p_query->>''state'')\n and case coalesce(p_query->>''tab'',''all'') when ''mine'' then exists(select 1 from public.advisory_matter_team tm where tm.matter_id=i.id and tm.user_id=auth.uid()) or i.next_owner_id=auth.uid()\n when ''overdue'' then i.has_overdue_work\n when ''missing'' then i.closed_at is null and i.next_action is null\n when ''closed'' then i.closed_at is not null else true end\n ), page as (\n select * from filtered order by case when p_query->>''sort''=''due'' then next_due end asc nulls last,created_at desc,id\n limit least(50,greatest(1,coalesce((p_query->>''limit'')::int,20))) offset greatest(0,coalesce((p_query->>''offset'')::int,0))\n ) select jsonb_build_object(''items'',coalesce((select jsonb_agg(to_jsonb(p)) from page p),''[]''),''total'',(select count(*) from filtered),\n ''summary'',(select jsonb_build_object(''open'',count(*) filter(where closed_at is null and status not in (''completed'',''cancelled'')),\n ''overdue'',count(*) filter(where has_overdue_work),''overdue_items'',coalesce(sum(overdue_item_count),0),''waiting'',count(*) filter(where closed_at is null and work_state=''waiting_client''),\n ''closed_week'',count(*) filter(where closed_at>=date_trunc(''week'',current_timestamp at time zone ''Asia/Bangkok'') at time zone ''Asia/Bangkok'')) from items),\n ''permissions'',jsonb_build_object(''manage'',public.advisory076_allowed(''manage''),''task'',public.advisory076_allowed(''task''),''delete'',public.advisory076_allowed(''delete''))) into result;\n if p_matter_id is not null then\n  if jsonb_array_length(result->''items'')<>1 then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n  result:=result||jsonb_build_object(\n   ''journey_path'',(select coalesce(jsonb_agg(to_jsonb(v) order by v.entered_at,v.recorded_at,v.id),''[]''::jsonb) from public.advisory_stage_visits v where v.matter_id=p_matter_id and v.kind=''visit''),\n   ''journey_decisions'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',a.id,''actor_id'',a.actor_id,''occurred_at'',a.occurred_at,''kind'',a.kind,''detail'',a.detail) order by a.occurred_at,a.id),''[]''::jsonb) from public.advisory_matter_activities a where a.matter_id=p_matter_id and a.detail->>''journey_format''=''2''),\n   ''journey_snapshot'',(select to_jsonb(j) from public.advisory_journey_snapshots j where matter_id=p_matter_id),\n   ''state_history'',(select coalesce(jsonb_agg(to_jsonb(x) order by x.started_at desc),''[]'') from (select work_state,started_at,ended_at,reason from public.advisory_work_state_events where matter_id=p_matter_id order by started_at desc limit 10) x),\n   ''team'',(select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object(''name'',coalesce(nullif(p.staff_name,''''),p.full_name)) order by t.team_role,p.full_name),''[]'') from public.advisory_matter_team t join public.user_profiles p on p.id=t.user_id where t.matter_id=p_matter_id),\n   ''stages'',(select coalesce(jsonb_agg(to_jsonb(s)||coalesce((select element-''key'' from public.advisory_journey_snapshots j, lateral jsonb_array_elements(j.definition->''stages'') element where j.matter_id=s.matter_id and element->>''key''=s.stage_key),''{}''::jsonb)||jsonb_build_object(''visits'',coalesce(v.rows,''[]''),''minutes'',tm.minutes,''elapsed_seconds'',(select sum(extract(epoch from coalesce(exited_at,current_timestamp)-entered_at)) from public.advisory_stage_visits where stage_id=s.id and kind=''visit''),''task_total'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null),''task_completed'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null and status=''completed''),''unclassified'',tm.unclassified) order by s.position),''[]'')\n    from public.advisory_matter_stages s\n    left join lateral(select jsonb_agg(to_jsonb(x) order by recorded_at desc) rows from (select * from public.advisory_stage_visits where stage_id=s.id order by recorded_at desc limit 20) x) v on true\n    left join lateral(select sum(minutes) minutes,count(*) filter(where stage_id is null) unclassified from public.advisory_time_logs where advisory_matter_id=p_matter_id and stage_id=s.id and deleted_at is null) tm on true where s.matter_id=p_matter_id),\n   ''time'',(select jsonb_build_object(''minutes'',coalesce(sum(minutes),0),''core'',coalesce(sum(minutes) filter(where billable),0),''support'',coalesce(sum(minutes) filter(where not billable),0),''unclassified'',count(*) filter(where stage_id is null)) from public.advisory_time_logs where advisory_matter_id=p_matter_id and deleted_at is null),\n   ''other_matters'',(select coalesce(jsonb_agg(to_jsonb(x)),''[]'') from (select id,matter_no,title,status from public.advisory_operational_matters where client_id=(select client_id from public.advisory_operational_matters where id=p_matter_id) and id<>p_matter_id order by created_at desc limit 5) x));\n end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_archive_uat(uuid,text,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_archive_uat(p_request_id uuid, p_reason text, p_reviewed jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE actor uuid:=auth.uid(); state jsonb; after_state jsonb; r record; n integer;\n moment timestamptz:=clock_timestamp();\nBEGIN\n IF NOT coalesce(public.advisory086_admin(),false) THEN\n  RAISE EXCEPTION ''ADVISORY_FORBIDDEN'' USING ERRCODE=''42501'';\n END IF;\n IF p_request_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000\n  OR p_reviewed IS NULL OR jsonb_typeof(p_reviewed)<>''object''\n  OR coalesce(p_reviewed->>''rows_sha256'','''') !~ ''^[0-9a-f]{64}$''\n  OR coalesce(p_reviewed->>''preserved_sha256'','''') !~ ''^[0-9a-f]{64}$''\n  OR coalesce(p_reviewed->>''targets_sha256'','''') !~ ''^[0-9a-f]{64}$''\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEW_REQUIRED''; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(''advisory095-fixed-uat-batch'',0));\n -- One-time maintenance operation: short, deterministic SHARE locks keep the\n -- whole reviewed preservation snapshot stable. No business table is written.\n FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n  WHERE c.relkind IN (''r'',''p'') AND NOT c.relispartition AND\n   (n.nspname=''public'' OR n.nspname=''auth'' AND c.relname=''users''\n    OR n.nspname=''storage'' AND c.relname IN (''buckets'',''objects''))\n  AND c.relname<>''advisory_matter_archives'' ORDER BY n.nspname COLLATE \"C\",c.relname COLLATE \"C\"\n LOOP EXECUTE format(''LOCK TABLE %I.%I IN SHARE MODE'',r.nspname,r.relname); END LOOP;\n LOCK TABLE public.advisory_matter_archives IN EXCLUSIVE MODE;\n IF NOT coalesce(public.advisory086_admin(),false) THEN\n  RAISE EXCEPTION ''ADVISORY_FORBIDDEN'' USING ERRCODE=''42501'';\n END IF;\n PERFORM m.id FROM public.advisory_matters m JOIN public.advisory095_targets() t ON t.id=m.id ORDER BY m.id FOR UPDATE OF m;\n SELECT public.advisory095_capture() INTO state;\n IF NOT coalesce((state->>''targets_exact'')::boolean,false) THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_IDENTITY_CHANGED''; END IF;\n IF (state->>''protected_count'')::integer<>9\n  OR (state#>>''{reviewed_special_evidence,time_023_minutes}'')::bigint<>90\n  OR (state#>>''{reviewed_special_evidence,audit_014_count}'')::bigint<1\n  OR state#>''{reviewed_special_evidence,snapshot_matters}''<>''[\"ADV-2026-019\",\"ADV-2026-020\",\"ADV-2026-021\",\"ADV-2026-022\",\"ADV-2026-023\"]''::jsonb\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEWED_EVIDENCE_CHANGED''; END IF;\n IF state->>''rows_sha256'' IS DISTINCT FROM p_reviewed->>''rows_sha256''\n  OR state->>''preserved_sha256'' IS DISTINCT FROM p_reviewed->>''preserved_sha256''\n  OR state->>''targets_sha256'' IS DISTINCT FROM p_reviewed->>''targets_sha256''\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEW_STALE''; END IF;\n IF state->''external_references''<>''[]''::jsonb THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_EXTERNAL_REFERENCE''; END IF;\n SELECT count(*) INTO n FROM public.advisory_matter_archives;\n IF n<>0 THEN\n  IF n=11 AND NOT EXISTS(SELECT 1 FROM public.advisory_matter_archives a\n    LEFT JOIN public.advisory095_targets() t ON t.id=a.matter_id AND t.matter_no=a.matter_no\n    WHERE t.id IS NULL OR a.request_id<>p_request_id OR a.archived_by<>actor\n     OR a.archive_reason<>btrim(p_reason) OR a.reviewed_baseline<>p_reviewed\n     OR a.reviewed_matter_sha256<>(SELECT encode(sha256(convert_to(to_jsonb(m)::text,''UTF8'')),''hex'')\n       FROM public.advisory_matters m WHERE m.id=a.matter_id))\n  THEN RETURN jsonb_build_object(''archived'',11,''request_id'',p_request_id,''replayed'',true); END IF;\n  RAISE EXCEPTION ''ADVISORY_ARCHIVE_RETRY_MISMATCH'';\n END IF;\n INSERT INTO public.advisory_matter_archives(matter_id,matter_no,archived_at,archived_by,archive_reason,request_id,reviewed_matter_sha256,reviewed_baseline)\n SELECT m.id,m.matter_no,moment,actor,btrim(p_reason),p_request_id,\n  encode(sha256(convert_to(to_jsonb(m)::text,''UTF8'')),''hex''),p_reviewed\n FROM public.advisory_matters m JOIN public.advisory095_targets() t ON t.id=m.id AND t.matter_no=m.matter_no;\n GET DIAGNOSTICS n=ROW_COUNT;\n IF n<>11 THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_TARGET_COUNT''; END IF;\n SELECT public.advisory095_capture() INTO after_state;\n IF state IS DISTINCT FROM after_state THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_PRESERVATION_FAILED''; END IF;\n RETURN jsonb_build_object(''archived'',n,''request_id'',p_request_id,''replayed'',false);\nEND $function$\n","volatility":"v","service_role":false,"authenticated":true},"advisory_control_section(uuid,text,integer,uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_section(p_matter_id uuid, p_section text, p_offset integer DEFAULT 0, p_issue_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare tab text; predicate text; ordering text; rows jsonb; total bigint;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n if not exists(select 1 from public.advisory_operational_matters where id=p_matter_id) then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n case p_section\n when ''tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is null and ($3 is null or advisory_issue_id=$3)''; ordering:=''case when status in (''''completed'''',''''cancelled'''') then 1 else 0 end,due_date nulls last,id'';\n when ''deleted_tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is not null and ($3 is null or advisory_issue_id=$3)''; ordering:=''deleted_at desc,id'';\n when ''activity'' then tab:=''advisory_matter_activities''; predicate:=''matter_id=$1''; ordering:=''occurred_at desc,id'';\n when ''deliverables'' then tab:=''advisory_deliverables''; predicate:=''matter_id=$1''; ordering:=''due_date nulls last,id'';\n when ''visits'' then tab:=''advisory_stage_visits''; predicate:=''matter_id=$1''; ordering:=''recorded_at desc,id'';\n when ''states'' then tab:=''advisory_work_state_events''; predicate:=''matter_id=$1''; ordering:=''started_at desc,id'';\n else raise exception ''ADVISORY_SECTION_INVALID''; end case;\n execute format(''select count(*) from public.%I where %s'',tab,predicate) into total using p_matter_id,p_offset,p_issue_id;\n execute format(''select coalesce(jsonb_agg(to_jsonb(t)),''''[]'''') from (select * from public.%I where %s order by %s limit 20 offset $2) t'',tab,predicate,ordering)\n into rows using p_matter_id,greatest(0,p_offset),p_issue_id;\n if p_section=''tasks'' then\n  -- Enrich the existing bounded Task page from the same canonical source once.\n  with overdue as materialized (select * from public.advisory_overdue_work(p_matter_id))\n  select coalesce(jsonb_agg(t.value||jsonb_build_object(''overdue_days'',coalesce(o.overdue_days,0)) order by t.position),''[]''::jsonb)\n  into rows from jsonb_array_elements(rows) with ordinality t(value,position)\n  left join overdue o on o.source=''task'' and o.source_id=(t.value->>''id'')::uuid;\n end if;\n return jsonb_build_object(''items'',rows,''total'',total);\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true}},"relations":{"advisory_matter_archives":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"kind":"r","view":null,"owner":"postgres","columns":[["matter_id","uuid",true,"","",null,null],["matter_no","text",true,"","",null,null],["archived_at","timestamp with time zone",true,"","",null,null],["archived_by","uuid",true,"","",null,null],["archive_reason","text",true,"","",null,null],["request_id","uuid",true,"","",null,null],["reviewed_matter_sha256","text",true,"",